14	package tech.pegasys.teku.infrastructure.async.runloop;
15	
16	import java.time.Duration;
17	import java.util.concurrent.CompletionException;
18	import tech.pegasys.teku.infrastructure.async.AsyncRunner;
19	import tech.pegasys.teku.infrastructure.async.ExceptionThrowingRunnable;
20	import tech.pegasys.teku.infrastructure.async.SafeFuture;
21	
22	public class AsyncRunLoop {
23	  private final RunLoopLogic logic;
24	  private final AsyncRunner asyncRunner;
25	  private final Duration retryDelay;
26	
27	  public AsyncRunLoop(
28	      final RunLoopLogic logic, final AsyncRunner asyncRunner, final Duration retryDelay) {
29	    this.logic = logic;
30	    this.asyncRunner = asyncRunner;
31	    this.retryDelay = retryDelay;
32	  }
33	
34	  public void start() {
35	    logic
36	        .init()
37	        .thenCompose(__ -> nextLoopAfterDelay())
38	        .finish(error -> onError(error, this::start));
39	  }
40	
41	  private void nextLoop() {
42	    logic
43	        .advance()
44	        .thenCompose(__ -> nextLoopAfterDelay())
45	        .finish(error -> onError(error, this::nextLoop));
46	  }
47	
48	  private SafeFuture<Void> nextLoopAfterDelay() {
49	    return asyncRunner.runAfterDelay(this::nextLoop, logic.getDelayUntilNextAdvance());
50	  }
51	
52	  private void onError(final Throwable error, final ExceptionThrowingRunnable retryAction) {
53	    if (error instanceof CompletionException && error.getCause() != null) {
54	      logic.onError(error.getCause());
55	    } else {
56	      logic.onError(error);
57	    }
58	    asyncRunner.runAfterDelay(retryAction, retryDelay).ifExceptionGetsHereRaiseABug();
59	  }
60	}
